'use strict';
// Node only. Bump release.json, then run node tools/prepare-release.cjs --write.
// --check verifies every generated byte and rejects stale or reused release numbers.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),cp=require('node:child_process');
const root=path.resolve(__dirname,'..'),args=process.argv.slice(2);
const write=args.includes('--write');
const read=(file)=>fs.readFileSync(path.join(root,file),'utf8');
const digest=(bytes)=>crypto.createHash('sha256').update(bytes).digest('hex');
const version=JSON.parse(read('release.json')).build;
if(!Number.isSafeInteger(version)||version<=0)throw Error('Invalid release build');
const plans=[
 {dir:'',name:'home',cache:'glass-home',scripts:['parked.js','drive-location.js','drive/link-core.js','drive-phone.js','drive/speed-check.js','drive/guide.js','drive/cameras.js','home-shell.js','watch-phone.js','watch-library.js','app.js']},
 {dir:'drive/',name:'drive',cache:'bakar-drive',scripts:['../drive-location.js','link-core.js','speed-check.js','guide.js','app.js']},
];
const pending=new Map();
function generated(file,body){pending.set(file,body);}
const files={};
for(const plan of plans){
 const {dir,name,cache,scripts}=plan;
 const alias=dir+'app.js';
 const app=read(alias).replace(/const APP_BUILD = \d+;/,'const APP_BUILD = '+version+';');
 if(!app.includes('const APP_BUILD = '+version+';'))throw Error('Missing executable build constant in '+alias);
 generated(alias,app);
 const bundle=scripts.map(file=>'// '+file+'\n'+(file==='app.js'?app:read(dir+file)).trimEnd()+'\n;\n').join('\n');
 const hash=digest(bundle),entry='runtime/'+name+'-v'+version+'-'+hash.slice(0,16)+'.js';
 generated(dir+entry,bundle);files[dir+entry]=hash;
 const html=read(dir+'index.html').replace(/<!-- app-entry -->[\s\S]*?<!-- end-app-entry -->/,
   '<!-- app-entry -->\n  <script src="'+entry+'"></script>\n  <!-- end-app-entry -->');
 if(!html.includes('src="'+entry+'"'))throw Error('Missing release entry markers in '+dir+'index.html');
 generated(dir+'index.html',html);
 const sw=read(dir+'sw.js').replace(/const CACHE = '[^']+';/,"const CACHE = '"+cache+'-v'+version+"';")
  .replace(/const ENTRY = '[^']+';/,"const ENTRY = '"+entry+"';");
 if(!sw.includes("const ENTRY = '"+entry+"';"))throw Error('Missing cache entry marker');
 generated(dir+'sw.js',sw);
 const local=[dir+'index.html',dir+'sw.js',dir+'style.css',dir+'manifest.webmanifest'];
 for(const file of local)files[file]=digest(pending.get(file)||read(file));
}
// Include separately loaded files (Review, camera database and vendors), not just the bundles.
const ignored=new Set(['.git','.github','.well-known','tools','tests','runtime']);
function lockSources(dir=''){
 for(const item of fs.readdirSync(path.join(root,dir),{withFileTypes:true}).sort((a,b)=>a.name<b.name?-1:a.name>b.name?1:0)){
  if(ignored.has(item.name))continue;
  const file=dir+item.name;
  if(item.isDirectory()){lockSources(file+'/');continue;}
  if(!/\.(js|css|html|json|webmanifest)$/.test(file)||['release.json','release-lock.json'].includes(file))continue;
  files[file]=digest(pending.get(file)||read(file));
 }
}
lockSources();
const lock={build:version,files};
const refOption=args.indexOf('--base');
const base=refOption>=0?args[refOption+1]:'HEAD';
const old=cp.spawnSync('git',['show',base+':release-lock.json'],{cwd:root,encoding:'utf8'});
if(old.status===0){
 const before=JSON.parse(old.stdout);
 if(before.build>version || (before.build===version && JSON.stringify(before.files)!==JSON.stringify(files)))
  throw Error('Runtime, worker or shell changed. Increment the build in release.json.');
}
generated('release-lock.json',JSON.stringify(lock,null,2)+'\n');
const stale=[];
for(const [file,body] of pending){
 let old;try{old=read(file);}catch{}
 if(old===body)continue;
 if(!write){stale.push(file);continue;}
 fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});fs.writeFileSync(path.join(root,file),body);
}
if(stale.length)throw Error('Outdated release outputs: '+stale.join(', '));
console.log('Verified Home and Drive executing build '+version);
